function parseDuration(s) {
    /**
     * Parse a duration string like '1d2h', '1h30m', '45s' or '2h5s' into total seconds.
     *
     * Accepts days (d), hours (h), minutes (m) and seconds (s) in any combination,
     * e.g. '1d2h' -> 93600, '1h30m' -> 5400, '45s' -> 45, '2h5s' -> 7205.
     *
     * @param {string} s - The duration string to parse.
     * @returns {number} The total duration in seconds.
     * @throws {Error} If the string is empty or contains invalid characters.
     */
    if (!s) {
        throw new Error("Duration string is empty");
    }

    const pattern = /(\d+)([dhms])/g;
    const matches = [...s.matchAll(pattern)];

    // Ensure the whole string was consumed by the pattern
    if (matches.map(([full]) => full).join('') !== s) {
        throw new Error(`Invalid duration string: ${s}`);
    }

    let total = 0;
    for (const [, value, unit] of matches) {
        const v = parseInt(value, 10);
        if (unit === 'd') {
            total += v * 86400;
        } else if (unit === 'h') {
            total += v * 3600;
        } else if (unit === 'm') {
            total += v * 60;
        } else if (unit === 's') {
            total += v;
        }
    }

    return total;
}
